-- Rentals Phase 47: authorised work execution and completion evidence.
begin;
create table public.rental_maintenance_work_events(id uuid primary key default gen_random_uuid(),request_id uuid not null references public.rental_maintenance_requests(id),quote_id uuid references public.rental_maintenance_quotes(id),organisation_id uuid not null references public.organisations(id),event_type text not null check(event_type in('work_authorized','work_started','progress_update','work_completed')),note text,evidence_link text,actual_cost numeric(14,2) check(actual_cost is null or actual_cost>=0),recorded_by uuid not null references auth.users(id),recorded_at timestamptz not null default now());
create index rental_maintenance_work_events_request_idx on public.rental_maintenance_work_events(request_id,recorded_at desc);alter table public.rental_maintenance_work_events enable row level security;revoke all on public.rental_maintenance_work_events from anon,authenticated;grant select on public.rental_maintenance_work_events to authenticated;create policy rental_maintenance_work_events_read on public.rental_maintenance_work_events for select to authenticated using(exists(select 1 from public.rental_maintenance_requests r join public.rental_properties p on p.id=r.property_id where r.id=request_id and public.rental_branch_access(p.organisation_id,p.branch_id)));
create or replace function public.rental_record_maintenance_work_event(p_request uuid,p_event text,p_note text default null,p_evidence text default null,p_cost numeric default null) returns jsonb language plpgsql security definer set search_path='' as $$declare r public.rental_maintenance_requests%rowtype;q public.rental_maintenance_quotes%rowtype;eid uuid;begin if auth.uid() is null or p_event not in('work_authorized','work_started','progress_update','work_completed') then raise exception 'Valid work event required';end if;if p_event='work_completed' and(length(btrim(coalesce(p_evidence,'')))=0 or p_cost is null or p_cost<0) then raise exception 'Completion requires evidence and actual cost';end if;select * into r from public.rental_maintenance_requests where id=p_request for update;if not found or not exists(select 1 from public.rental_properties p where p.id=r.property_id and public.rental_branch_access(p.organisation_id,p.branch_id)) then raise exception 'Not authorized';end if;select * into q from public.rental_maintenance_quotes where request_id=r.id and status='approved' limit 1;if p_event in('work_authorized','work_started','work_completed') and q.id is null then raise exception 'An approved quote is required before work can proceed';end if;if p_event='work_started' then update public.rental_maintenance_requests set status='assigned' where id=r.id;end if;if p_event='work_completed' then update public.rental_maintenance_requests set status='resolved' where id=r.id;update public.rental_maintenance_assignments set status='completed' where request_id=r.id;end if;insert into public.rental_maintenance_work_events(request_id,quote_id,organisation_id,event_type,note,evidence_link,actual_cost,recorded_by)values(r.id,q.id,r.organisation_id,p_event,nullif(btrim(coalesce(p_note,'')),''),nullif(btrim(coalesce(p_evidence,'')),''),p_cost,auth.uid()) returning id into eid;return jsonb_build_object('event_id',eid,'request_id',r.id,'event_type',p_event);end$$;
revoke execute on function public.rental_record_maintenance_work_event(uuid,text,text,text,numeric) from public,anon;grant execute on function public.rental_record_maintenance_work_event(uuid,text,text,text,numeric) to authenticated;commit;
